export function capturedPentagramStroke(index: number): number[] {
  const path = PATHS[index];
  if (path === undefined) throw new RangeError("Unknown captured pentagram.");
  return path.split(" ").flatMap((pair) => [...pair.split(",").map(Number), 0.5]);
}

export function capturedPentagramPoints(index: number) {
  const samples = capturedPentagramStroke(index);
  return Array.from({ length: samples.length / 3 }, (_, offset) => ({
    x: samples[offset * 3]!,
    y: samples[offset * 3 + 1]!,
  }));
}
